package kernels

// The amd64 and arm64 assembly of this package is generated by go-asmgen. The
// float64 sum, sqrt, max/min and elementwise kernels, and the exp/log kernels,
// live in go-simd/floats since K1 of the go-scikit performance campaign; what is
// generated here is GEMM, the float64 dot, and the float32 elementwise, sqrt
// and pairwise-block kernels. The float32 extrema (Max32/Min32) moved to
// go-simd/floats as Float32Max/Float32Min (go-ndarray/ndarray#98).
//
//go:generate sh -c "cd asmgen/amd64 && GOFLAGS=-mod=mod go run gen.go && mv sum_amd64.s ../../sum_amd64.s"
//go:generate sh -c "cd asmgen/arm64 && GOFLAGS=-mod=mod go run gen.go && mv sum_arm64.s ../../sum_arm64.s"
